contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single-entry test function
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // to send Ether, require the test contract has enough balance
        require(address(this).balance >= amount);

        // read balances before
        uint256 beforeUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeContractEth = address(c).balance;

        // attempt to add to balance and capture whether it reverted
        bool addReverted;
        c.addToBalance{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            addReverted = true;
        } else {
            addReverted = false;
        }

        // read balances after the add attempt
        uint256 afterUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterContractEth = address(c).balance;

        // General invariant:
        // - If the add did not revert: afterUser == beforeUser + amount AND afterContractEth == beforeContractEth + amount
        // - If the add reverted: afterUser == beforeUser AND afterContractEth == beforeContractEth
        assert(
            (!addReverted && afterUser == beforeUser + amount && afterContractEth == beforeContractEth + amount)
            ||
            (addReverted && afterUser == beforeUser && afterContractEth == beforeContractEth)
        );
    }

    // accept ETH when C sends funds back
    receive() external payable {}
}

