// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeUser;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeUser = __r; } catch { return; }
        uint256 beforeContractEth = address(c).balance;
        bool addReverted;
        try c.addToBalance{value: amount}() {
            addReverted = false;
        } catch {
            addReverted = true;
        }
        uint256 afterUser;
        try c.getBalance(address(this)) returns (uint256 __r) { afterUser = __r; } catch { return; }
        uint256 afterContractEth = address(c).balance;
        assertTrue((!addReverted && afterUser == beforeUser + amount && afterContractEth == beforeContractEth + amount)
            ||
            (addReverted && afterUser == beforeUser && afterContractEth == beforeContractEth));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
